// define function to preprocess text using NLP techniques
func preprocessText(text string) []string {
 // tokenize text using Kagome tokenizer
 tok := tokenizer.New()
 tokens := tok.Tokenize(text)
 // lemmatize tokens using Snowball stemmer
 stemmed := make([]string, len(tokens))
 for i, token := range tokens {
 stem, _ := snowball.Stem(token.Surface, english.Stemmer)
 stemmed[i] = stem
 }
 return stemmed
}
// define function to group similar demands together using k-means clustering
func clusterDemands(demands []string) [][]string {
 // preprocess demands using NLP techniques
 preprocessed := make([][]float64, len(demands))
 for i, demand := range demands {
 preprocessed[i] = preprocessText(demand)
 }
 // create document-term matrix from preprocessed demands
 dtm := mat.NewDense(len(demands), len(preprocessed[0]), nil)
 for i, row := range preprocessed {
 for j, val := range row {
 dtm.Set(i, j, val)
